using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.AI;

// 1. Define strongly-typed domain record
public record CustomerRiskAssessment(
    [property: JsonPropertyName("riskLevel")] string RiskLevel,
    [property: JsonPropertyName("score")] int Score,
    [property: JsonPropertyName("flags")] string[] Flags,
    [property: JsonPropertyName("recommendedAction")] string RecommendedAction,
    [property: JsonPropertyName("auditSummary")] string AuditSummary
);

public class StructuredOutputService
{
    private readonly IChatClient _chatClient;

    public StructuredOutputService(IChatClient chatClient)
    {
        _chatClient = chatClient;
    }

    public async Task<CustomerRiskAssessment> AnalyzeRiskAsync(
        string customerHistory,
        CancellationToken ct = default)
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are an enterprise risk analyst. Evaluate the customer profile and return strict JSON."),
            new(ChatRole.User, customerHistory)
        };

        // 2. Request structured output schema conformance
        var options = new ChatOptions
        {
            ResponseFormat = ChatResponseFormat.ForJsonSchema<CustomerRiskAssessment>(
                schemaName: "CustomerRiskAssessment",
                schemaDescription: "Detailed risk rating and recommended mitigation actions")
        };

        ChatCompletion response = await _chatClient.CompleteAsync(messages, options, ct);
        var json = response.Message.Text ?? "{}";

        // 3. Deserialize safely with strong typing
        var assessment = JsonSerializer.Deserialize<CustomerRiskAssessment>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true });

        return assessment ?? throw new InvalidOperationException("Failed to deserialize risk assessment.");
    }
}
